CREATE TABLE IF NOT EXISTS `dpn_medical_rehab_plans` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`patient_cid` varchar(64) NOT NULL,`body_part` varchar(32) NULL,`reason` varchar(255) NULL,`sessions_required` int NOT NULL,`sessions_completed` int NOT NULL DEFAULT 0,`status` varchar(32) NOT NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_rehab_patient` (`patient_cid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
